<?php
declare(strict_types=1);
namespace BSPProcess;
const C=299792458.0;
function specs():array{return [
'rates'=>['title'=>'Gravity, motion and physical process rates','summary'=>'Compare two stipulated atomic-transition responses and an illustrative decay process against a conventional weak-field clock reference, without changing the assumed common progression.','equation'=>'δref ≈ gΔh/c² − β²/(1+√(1−β²)); δi = αi gΔh/c² + ηi δSR','params'=>[['hours','Common reference interval (hours)',6,0.1,48],['height','Height difference (m)',1000,-10000,10000],['speed','Relative speed (m/s)',7500,0,3000000],['alpha_a','Transition A gravity response',1,0,2],['eta_a','Transition A motion response',1,0,2],['alpha_b','Transition B gravity response',1,0,2],['eta_b','Transition B motion response',1,0,2],['alpha_decay','Decay gravity response',1,0,2],['eta_decay','Decay motion response',1,0,2],['half_life','Reference half-life (hours)',6,.1,48]],'limitation'=>'Conventional reference: uniform weak terrestrial gravity, constant relative speed and a common chosen coordinate interval; cross terms and field variation neglected. Candidate coefficients are freely stipulated, not microscopic laws or fitted results. Different transitions and particle decays require independent tests. A universal time postulate does not establish a preferred frame.'],
'synchronization'=>['title'=>'Remote synchronization and the dinner deadline','summary'=>'Use a four-timestamp exchange to see why a shared ordering premise does not supply an operational synchronization method or guarantee that a remote appointment can be reached.','equation'=>'θ̂ = [(t₂−t₁)+(t₃−t₄)]/2; θ̂−θ = (dout−dback)/2','params'=>[['offset','True remote clock offset (s)',2,-100,100],['outbound','Outbound signal delay (s)',3,0,3600],['return','Return signal delay (s)',5,0,3600],['turnaround','Remote turnaround (s)',1,0,600],['deadline','Home deadline after first transmission (s)',60,1,14400]],'limitation'=>'Synthetic timestamps use equal clock rates over a single exchange and stipulated nonnegative signal delays. The two-way estimate assumes symmetric delay; an asymmetric delay creates an offset bias. Receipt before the deadline is a communication condition only, not a proof of travel feasibility, universal simultaneity, or instantaneous communication.']];}
function calculate(string $id,array $input=[]):array{
 $s=specs()[$id]??throw new \InvalidArgumentException('Unknown process model');$p=[];foreach($s['params'] as [$k,$label,$d,$lo,$hi]){$v=array_key_exists($k,$input)?$input[$k]:$d;if(!is_numeric($v)||is_bool($v)||!is_finite((float)$v)||(float)$v<$lo||(float)$v>$hi)throw new \InvalidArgumentException('Invalid parameter: '.$k);$p[$k]=(float)$v;}if(array_diff_key($input,$p))throw new \InvalidArgumentException('Unknown parameter');
 if($id==='rates'){$beta=$p['speed']/C;$grav=9.80665*$p['height']/C**2;$kin=-$beta**2/(1+sqrt(1-$beta**2));$ref=$grav+$kin;$a=$p['alpha_a']*$grav+$p['eta_a']*$kin;$b=$p['alpha_b']*$grav+$p['eta_b']*$kin;$d=$p['alpha_decay']*$grav+$p['eta_decay']*$kin;$T=$p['hours']*3600;$tau=$p['half_life']*3600;$surv=exp(-log(2)*$T*(1+$d)/$tau);$m=['Common reference interval (s)'=>$T,'Gravity fractional shift'=>$grav,'Motion fractional shift'=>$kin,'Conventional reference shift'=>$ref,'Transition A shift'=>$a,'Transition B shift'=>$b,'A minus B fractional shift'=>$a-$b,'A minus reference accumulation (s)'=>($a-$ref)*$T,'B minus reference accumulation (s)'=>($b-$ref)*$T,'Candidate survival fraction'=>$surv,'Reference survival fraction'=>exp(-log(2)*$T*(1+$ref)/$tau)];$cols=['Reference interval (h)','Reference clock offset (s)','Transition A offset (s)','Transition B offset (s)'];$rows=[];for($i=0;$i<=120;$i++){$h=$p['hours']*$i/120;$rows[]=[$h,$h*3600*$ref,$h*3600*$a,$h*3600*$b];}}
 else{$t1=0.0;$t2=$p['outbound']+$p['offset'];$t3=$t2+$p['turnaround'];$t4=$p['outbound']+$p['turnaround']+$p['return'];$estimate=(($t2-$t1)+($t3-$t4))/2;$m=['Home send timestamp t1 (s)'=>$t1,'Remote receive timestamp t2 (s)'=>$t2,'Remote send timestamp t3 (s)'=>$t3,'Home receive timestamp t4 (s)'=>$t4,'True offset (s)'=>$p['offset'],'Estimated offset (s)'=>$estimate,'Offset error (s)'=>$estimate-$p['offset'],'Round trip signal time (s)'=>$t4-$p['turnaround'],'Home deadline (s)'=>$p['deadline'],'Time remaining after reply (s)'=>$p['deadline']-$t4];$cols=['Return signal delay (s)','Estimated offset (s)','True offset (s)','Offset error (s)'];$rows=[];$max=max(1,$p['outbound'],$p['return'])*2;for($i=0;$i<=120;$i++){$x=$max*$i/120;$err=($p['outbound']-$x)/2;$rows[]=[$x,$p['offset']+$err,$p['offset'],$err];}}
 return ['schema'=>'beyondspacetime.process-rates.v1','version'=>'2.5.0','model'=>$id,'parameters'=>$p,'metrics'=>$m,'columns'=>$cols,'rows'=>$rows,'limitation'=>$s['limitation'],'solver_sha256'=>hash_file('sha256',__FILE__)];
}
